import { gsap } from "gsap";
import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "../../motion/usePrefersReducedMotion";
import "./brand-plate.css";

/**
 * 开场动画，缩在书架左上角那块 Leafia 铭牌里。
 *
 * 以前它是盖住整页的幕布：五线谱扫过、音符飞出、LEAFIA 一个个立起来，
 * 再慢慢掀开露出房间。现在房间本身就是正门，幕布没有意义了 ——
 * 同一套动作搬进铭牌：谱线在牌子里铺开、音符浮起来、字母逐个升起、
 * 分隔线拉直、那行小字最后落位。铭牌什么时候滑进来（`armed`），它就开始。
 *
 * prefers-reduced-motion：不演，直接是排好的样子。
 */

const WORDMARK = "Leafia";
const NOTES = ["♪", "♩", "♫", "♬", "♩"];

export function BrandPlate({ armed }: { armed: boolean }) {
  const prefersReducedMotion = usePrefersReducedMotion();
  const rootRef = useRef<HTMLSpanElement>(null);
  const playedRef = useRef(false);

  useEffect(() => {
    if (!armed || playedRef.current) return undefined;
    playedRef.current = true;
    const root = rootRef.current;
    if (!root || prefersReducedMotion) return undefined;

    const ctx = gsap.context(() => {
      const staves = root.querySelectorAll(".brand-plate__staff-line");
      const notes = root.querySelectorAll(".brand-plate__note");
      const letters = root.querySelectorAll(".brand-plate__letter-glyph");
      const mark = root.querySelector(".brand-plate__mark");

      // 字母先藏在自己的窗口下面，等时间线把它们推上来。
      gsap.set(letters, { yPercent: 116, rotate: 3 });

      const tl = gsap.timeline({ defaults: { ease: "power3.out" } });
      tl.fromTo(
        mark,
        { scale: 0.5, rotate: -22, opacity: 0 },
        { scale: 1, rotate: 0, opacity: 1, duration: 0.6, ease: "back.out(1.6)" },
      )
        .fromTo(
          staves,
          {
            scaleX: 0,
            // 隔一条换一次原点，五条谱线织在一起，不像盖了一个章。
            transformOrigin: (index: number) =>
              index % 2 === 0 ? "left center" : "right center",
          },
          { scaleX: 1, duration: 0.5, stagger: 0.055 },
          "-=0.34",
        )
        .fromTo(
          notes,
          { opacity: 0, x: 26, y: 14, scale: 0.4, rotate: -14 },
          {
            opacity: 1,
            x: 0,
            y: 0,
            scale: 1,
            rotate: (index: number) => -6 + index * 3,
            duration: 0.5,
            stagger: 0.07,
            ease: "back.out(1.5)",
          },
          "-=0.42",
        )
        .to(
          letters,
          { yPercent: 0, rotate: 0, duration: 0.56, stagger: 0.036 },
          "-=0.42",
        )
        .fromTo(
          root.querySelector(".brand-plate__rule"),
          { scaleX: 0 },
          { scaleX: 1, duration: 0.42, ease: "power2.out" },
          "-=0.3",
        )
        .fromTo(
          root.querySelector(".brand-plate__tagline"),
          { opacity: 0, y: 8 },
          { opacity: 1, y: 0, duration: 0.4 },
          "-=0.3",
        );
    }, root);

    return () => ctx.revert();
  }, [armed, prefersReducedMotion]);

  return (
    <span className="brand-plate" ref={rootRef}>
      {/* 开场那五线谱与音符：现在是铭牌的底纹，不是幕布。 */}
      <span className="brand-plate__staff" aria-hidden="true">
        {Array.from({ length: 5 }, (_, index) => (
          <i key={index} className="brand-plate__staff-line" />
        ))}
      </span>
      <span className="brand-plate__notes" aria-hidden="true">
        {NOTES.map((note, index) => (
          <span key={`${note}-${index}`} className="brand-plate__note">
            {note}
          </span>
        ))}
      </span>

      <span className="home-lobby__brand-mark brand-plate__mark" aria-hidden="true">
        <img src="/leafia-mark.svg" alt="" />
      </span>
      <span className="home-lobby__brand-copy brand-plate__copy">
        <strong className="brand-plate__word">
          {WORDMARK.split("").map((letter, index) => (
            <span key={`${letter}-${index}`} className="brand-plate__letter">
              <i className="brand-plate__letter-glyph">{letter}</i>
            </span>
          ))}
        </strong>
        <span className="brand-plate__rule" aria-hidden="true" />
        <small className="brand-plate__tagline">Moonlit knowledge space</small>
      </span>
    </span>
  );
}

export default BrandPlate;
