import {
  forwardRef,
  useEffect,
  useImperativeHandle,
  useRef,
  useState,
  type CSSProperties,
  type PointerEvent as ReactPointerEvent,
} from "react";
import { usePrefersReducedMotion } from "../../../motion/usePrefersReducedMotion";
import "./elastic-reel.css";

export interface ElasticReelItem {
  src: string;
  alt: string;
  title?: string;
  subtitle?: string;
  focus?: number;
}

export interface ElasticReelHandle {
  open: (index: number) => void;
  close: () => void;
  next: () => void;
  previous: () => void;
}

interface ElasticReelProps {
  items: ElasticReelItem[];
  defaultOpen?: number;
  barWidth?: number;
  barHeight?: number;
  gap?: number;
  radius?: number;
  magnify?: number;
  lift?: number;
  influence?: number;
  align?: "center" | "bottom";
  openSize?: number;
  openAspect?: number;
  elasticity?: number;
  blur?: number;
  dim?: number;
  shadow?: number;
  rim?: number;
  autoplay?: "sweep" | "cycle" | "off";
  speed?: number;
  interval?: number;
  pauseOnHover?: boolean;
  draggable?: boolean;
  wheel?: boolean;
  captions?: boolean;
  labels?: boolean;
  backgroundColor?: string;
  paused?: boolean;
  dpr?: number;
  ariaLabel?: string;
  onOpen?: (item: ElasticReelItem, index: number) => void;
  onClose?: () => void;
  className?: string;
  style?: CSSProperties;
}

export const ElasticReel = forwardRef<ElasticReelHandle, ElasticReelProps>(
  function ElasticReel(
    {
      items,
      defaultOpen = -1,
      barWidth = 44,
      barHeight = 0.5,
      gap = 10,
      radius = 12,
      magnify = 2.4,
      lift = 1.15,
      influence = 200,
      align = "center",
      openSize = 0.72,
      openAspect = 1,
      elasticity = 0.35,
      blur = 0.5,
      dim = 0.45,
      shadow = 0.35,
      rim = 0.12,
      autoplay = "sweep",
      speed = 1.4,
      interval = 4,
      pauseOnHover = true,
      draggable = true,
      wheel = true,
      captions = true,
      labels = true,
      backgroundColor = "transparent",
      paused = false,
      dpr = 2,
      ariaLabel = "Elastic book reel",
      onOpen,
      onClose,
      className = "",
      style,
    },
    ref,
  ) {
    const rootRef = useRef<HTMLDivElement>(null);
    const dragRef = useRef<{ x: number; index: number } | null>(null);
    const [hovered, setHovered] = useState(0);
    const [pointerHover, setPointerHover] = useState(false);
    const [openIndex, setOpenIndex] = useState(
      defaultOpen >= 0 && defaultOpen < items.length ? defaultOpen : -1,
    );
    const reduceMotion = usePrefersReducedMotion();

    const openAt = (index: number) => {
      if (!items.length) return;
      const next = Math.max(0, Math.min(index, items.length - 1));
      setOpenIndex(next);
      onOpen?.(items[next]!, next);
    };

    const close = () => {
      setOpenIndex(-1);
      onClose?.();
    };

    useImperativeHandle(
      ref,
      () => ({
        open: openAt,
        close,
        next: () => openAt((openIndex < 0 ? hovered : openIndex) + 1),
        previous: () => openAt((openIndex < 0 ? hovered : openIndex) - 1),
      }),
      [hovered, openIndex, items],
    );

    useEffect(() => {
      if (
        paused ||
        reduceMotion ||
        autoplay !== "cycle" ||
        items.length < 2 ||
        (pauseOnHover && pointerHover)
      ) {
        return undefined;
      }
      const timer = window.setInterval(
        () => openAt((openIndex + 1) % items.length),
        Math.max(1.5, interval) * 1000,
      );
      return () => window.clearInterval(timer);
    }, [
      autoplay,
      interval,
      items.length,
      openIndex,
      pauseOnHover,
      paused,
      pointerHover,
      reduceMotion,
      hovered,
    ]);

    const updateHover = (clientX: number) => {
      const root = rootRef.current;
      if (!root) return;
      const rect = root.getBoundingClientRect();
      const pitch = barWidth + gap;
      const reelWidth = items.length * pitch - gap;
      const start = (rect.width - reelWidth) / 2;
      const index = Math.round((clientX - rect.left - start) / pitch);
      setHovered(Math.max(0, Math.min(items.length - 1, index)));
    };

    const onPointerDown = (event: ReactPointerEvent<HTMLDivElement>) => {
      if (!draggable || event.button !== 0) return;
      dragRef.current = { x: event.clientX, index: hovered };
      event.currentTarget.setPointerCapture(event.pointerId);
    };

    const onPointerMove = (event: ReactPointerEvent<HTMLDivElement>) => {
      updateHover(event.clientX);
      if (!dragRef.current) return;
      const delta = Math.round(
        (event.clientX - dragRef.current.x) / (barWidth + gap),
      );
      setHovered(
        Math.max(
          0,
          Math.min(items.length - 1, dragRef.current.index + delta),
        ),
      );
    };

    const onPointerUp = (event: ReactPointerEvent<HTMLDivElement>) => {
      dragRef.current = null;
      if (event.currentTarget.hasPointerCapture(event.pointerId)) {
        event.currentTarget.releasePointerCapture(event.pointerId);
      }
    };

    const onWheel = (event: React.WheelEvent<HTMLDivElement>) => {
      if (!wheel || openIndex < 0 || Math.abs(event.deltaY) < 4) return;
      event.preventDefault();
      openAt(openIndex + (event.deltaY > 0 ? 1 : -1));
    };

    const activeItem = openIndex >= 0 ? items[openIndex] : undefined;

    return (
      <div
        ref={rootRef}
        className={`elastic-reel ${className}`}
        style={
          {
            ...style,
            "--er-bar-width": `${barWidth}px`,
            "--er-bar-height": `${
              typeof barHeight === "number" && barHeight <= 1
                ? barHeight * 100
                : barHeight
            }%`,
            "--er-gap": `${gap}px`,
            "--er-radius": `${radius}px`,
            "--er-magnify": magnify,
            "--er-lift": lift,
            "--er-open-size": openSize,
            "--er-open-aspect": openAspect || 1,
            "--er-blur": `${blur * 4}px`,
            "--er-dim": dim,
            "--er-shadow": shadow,
            "--er-rim": rim,
            "--er-background": backgroundColor,
            "--er-dpr": dpr,
          } as CSSProperties
        }
        aria-label={ariaLabel}
        onPointerEnter={() => setPointerHover(true)}
        onPointerLeave={() => setPointerHover(false)}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onWheel={onWheel}
      >
        {activeItem ? (
          <button
            type="button"
            className="elastic-reel__open"
            onClick={close}
            aria-label={`关闭 ${activeItem.title ?? activeItem.alt}`}
          >
            <img src={activeItem.src} alt={activeItem.alt} />
          </button>
        ) : null}

        <div className="elastic-reel__viewport">
          <div className="elastic-reel__bars" data-align={align}>
            {items.map((item, index) => {
              const distance = Math.abs(hovered - index);
              const effect =
                distance > influence / (barWidth + gap)
                  ? 0
                  : 1 - distance / (influence / (barWidth + gap));
              const isHovered = index === hovered;
              const isOpen = index === openIndex;
              return (
                <button
                  key={item.src}
                  type="button"
                  className="elastic-reel__bar"
                  style={
                    {
                      width: isHovered
                        ? `calc(var(--er-bar-width) * var(--er-magnify))`
                        : "var(--er-bar-width)",
                      height: isHovered
                        ? `calc(var(--er-bar-height) * var(--er-lift))`
                        : "var(--er-bar-height)",
                      opacity:
                        openIndex >= 0 && !isOpen
                          ? Math.max(0.18, 1 - dim)
                          : 1,
                      filter:
                        openIndex >= 0 && !isOpen
                          ? `blur(var(--er-blur))`
                          : "none",
                      zIndex: isOpen ? items.length + 1 : Math.round(effect * 10),
                    } as CSSProperties
                  }
                  onClick={() => {
                    if (isOpen) close();
                    else openAt(index);
                  }}
                  onFocus={() => setHovered(index)}
                  onKeyDown={(event) => {
                    if (event.key === "ArrowRight") {
                      event.preventDefault();
                      setHovered((current) => Math.min(items.length - 1, current + 1));
                    }
                    if (event.key === "ArrowLeft") {
                      event.preventDefault();
                      setHovered((current) => Math.max(0, current - 1));
                    }
                  }}
                  aria-label={item.title ?? item.alt}
                >
                  <img
                    src={item.src}
                    alt=""
                    style={{
                      objectPosition: `50% ${Math.round((item.focus ?? 0.5) * 100)}%`,
                    }}
                    draggable={false}
                  />
                </button>
              );
            })}
          </div>
        </div>

        {labels ? (
          <span className="elastic-reel__label">
            {items[hovered]?.title ?? items[hovered]?.alt ?? ""}
          </span>
        ) : null}
        {captions && activeItem ? (
          <span className="elastic-reel__caption">
            <strong>{activeItem.title ?? activeItem.alt}</strong>
            {activeItem.subtitle ? <small>{activeItem.subtitle}</small> : null}
          </span>
        ) : null}
      </div>
    );
  },
);

export default ElasticReel;
