import { motion } from "motion/react";
import { useState, type CSSProperties } from "react";
import "./page-flip.css";

export interface PageFlipLeaf {
  id?: string;
  front: string;
  back: string;
  alt?: string;
}

interface PageFlipProps {
  pages: PageFlipLeaf[];
  pageWidth?: number;
  pageHeight?: number;
  pageRadius?: number;
  pageColor?: string;
  perspective?: number;
  spineShift?: number;
  turnAngle?: number;
  peekAngle?: number;
  duration?: number;
  stagger?: number;
  ease?: "easeInOut" | "easeOut" | "circOut" | "backOut";
  shadow?: number;
  trigger?: "click" | "hover";
  closeOnLeave?: boolean;
  interactive?: boolean;
  className?: string;
  style?: CSSProperties;
}

export function PageFlip({
  pages,
  pageWidth = 220,
  pageHeight = 320,
  pageRadius = 4,
  pageColor = "#f4f4f4",
  perspective = 1200,
  spineShift = 110,
  turnAngle = 180,
  peekAngle = 10,
  duration = 0.55,
  stagger = 0.08,
  shadow = 0.3,
  ease = "easeInOut",
  trigger = "click",
  closeOnLeave = true,
  interactive = true,
  className = "",
  style,
}: PageFlipProps) {
  const [turned, setTurned] = useState<Set<number>>(() => new Set());

  const toggle = (index: number) => {
    if (!interactive) return;
    setTurned((current) => {
      const next = new Set(current);
      if (next.has(index)) next.delete(index);
      else next.add(index);
      return next;
    });
  };

  const reset = () => {
    if (!interactive || !closeOnLeave) return;
    setTurned(new Set());
  };

  return (
    <div
      className={`page-flip ${className}`}
      style={
        {
          ...style,
          "--pf-width": `${pageWidth}px`,
          "--pf-height": `${pageHeight}px`,
          "--pf-radius": `${pageRadius}px`,
          "--pf-paper": pageColor,
          "--pf-perspective": `${perspective}px`,
          "--pf-spine": `${spineShift}px`,
          "--pf-duration": `${duration}s`,
          "--pf-shadow": shadow,
        } as CSSProperties
      }
      onPointerLeave={reset}
    >
      <div className="page-flip__scene">
        {pages.map((page, index) => {
          const isTurned = turned.has(index);
          return (
            <motion.button
              key={page.id ?? `${page.alt ?? "page"}-${index}`}
              type="button"
              className="page-flip__leaf"
              aria-label={
                page.alt ?? (isTurned ? `返回第 ${index + 1} 页` : `翻到下一页`)
              }
              onPointerEnter={() => {
                if (trigger === "hover" && !isTurned) toggle(index);
              }}
              onClick={() => toggle(index)}
              initial={false}
              animate={{
                rotateY: isTurned ? -turnAngle : 0,
                x: isTurned ? spineShift * 0.14 : 0,
                zIndex: isTurned ? index : pages.length - index,
              }}
              transition={{
                duration,
                delay: isTurned ? index * stagger : 0,
                ease,
              }}
              style={{ zIndex: pages.length - index }}
            >
              <span className="page-flip__face page-flip__face--front">
                <img src={page.front} alt="" draggable={false} />
              </span>
              <span className="page-flip__face page-flip__face--back">
                <img src={page.back} alt="" draggable={false} />
              </span>
            </motion.button>
          );
        })}
      </div>
      <span className="page-flip__hint">
        {turned.size ? "点击已翻页返回" : "点击翻页"}
      </span>
    </div>
  );
}

export default PageFlip;
