import {
  ArrowLeft,
  BookmarkPlus,
  Check,
  Play,
  Waves,
} from "lucide-react";
import { motion } from "motion/react";
import { useState } from "react";
import { cn } from "../../lib/cn";
import { speakEnglish } from "../../lib/speak";
import {
  SOUND_MAKER_ITEMS,
  SPEECH_ORGANS,
  type SpeechOrgan,
} from "./languageLabData";
import type { CollectedWord } from "./WordsExplorer";

// 语音室用英音，语速比词典稍慢一点，跟着示范读。
function speakWord(word: string) {
  speakEnglish(word, { lang: "en-GB", rate: 0.82 });
}

export function PhoneticsStudio({
  savedIds,
  onBack,
  onSave,
  onDiscovery,
}: {
  savedIds: string[];
  onBack: () => void;
  onSave: (item: CollectedWord) => void;
  onDiscovery: (id: string, title: string) => void;
}) {
  const [organ, setOrgan] = useState<SpeechOrgan>(SPEECH_ORGANS[0]!);
  const [soundIndex, setSoundIndex] = useState(0);
  const sound = SOUND_MAKER_ITEMS[soundIndex]!;
  const organSaveId = `language-organ-${organ.id}`;
  const organSaved = savedIds.includes(organSaveId);

  const selectOrgan = (nextOrgan: SpeechOrgan) => {
    setOrgan(nextOrgan);
    onDiscovery(
      `language-organ-${nextOrgan.id}`,
      `${nextOrgan.english} observed`,
    );
  };

  return (
    <motion.div
      className="phonetics-studio"
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -8 }}
    >
      <header className="language-lab__subheader">
        <button type="button" onClick={onBack}>
          <ArrowLeft size={15} />
          Sound Lab
        </button>
        <div>
          <span className="eyebrow">How are sounds produced?</span>
          <h2>Phonetics Studio</h2>
        </div>
        <span>Articulatory phonetics</span>
      </header>

      <div className="phonetics-studio__body">
        <section className="phonetics-studio__diagram">
          <svg viewBox="0 0 480 360" aria-label="Speech organs diagram">
            <path
              className="speech-profile"
              d="M104 318 C95 250 106 186 152 136 C190 94 246 63 317 68 C367 72 405 102 414 144 C421 177 406 204 382 216 C359 228 329 227 310 236 C292 244 279 263 277 292 L277 318 Z"
            />
            <path
              className={cn(
                "speech-cavity",
                "speech-cavity--nasal",
                organ.id === "nasal" && "is-active",
              )}
              d="M235 120 C266 88 332 83 380 107 C397 116 402 142 389 151 C360 171 284 164 244 145 Z"
              onClick={() => selectOrgan(SPEECH_ORGANS[2]!)}
            />
            <path
              className={cn(
                "speech-cavity",
                "speech-cavity--oral",
                organ.id === "oral" && "is-active",
              )}
              d="M236 178 C268 155 344 153 379 181 C393 192 379 213 355 223 C320 238 266 232 239 213 C225 203 224 188 236 178 Z"
              onClick={() => selectOrgan(SPEECH_ORGANS[1]!)}
            />
            <path
              className={cn(
                "speech-cavity",
                "speech-cavity--pharyngeal",
                organ.id === "pharyngeal" && "is-active",
              )}
              d="M226 218 C248 232 269 254 273 292 L273 318 L200 318 C201 278 208 242 226 218 Z"
              onClick={() => selectOrgan(SPEECH_ORGANS[0]!)}
            />
            <text x="310" y="119">NASAL</text>
            <text x="329" y="183">ORAL</text>
            <text x="238" y="294">PHARYNGEAL</text>
          </svg>
          <div className="phonetics-studio__organ-list">
            {SPEECH_ORGANS.map((item) => (
              <button
                type="button"
                key={item.id}
                className={organ.id === item.id ? "is-active" : ""}
                onClick={() => selectOrgan(item)}
              >
                <strong>{item.english}</strong>
                <small>{item.role}</small>
              </button>
            ))}
          </div>
        </section>

        <aside className="phonetics-studio__detail">
          <span className="eyebrow">Selected organ</span>
          <h3>{organ.english}</h3>
          <strong>{organ.label} · {organ.role}</strong>
          <p>{organ.detail}</p>
          <div>
            {organ.sounds.map((item) => (
              <span key={item}>{item}</span>
            ))}
          </div>
          <button
            type="button"
            className={cn("language-lab__save", organSaved && "is-saved")}
            disabled={organSaved}
            onClick={() =>
              onSave({
                id: organSaveId,
                title: `${organ.english} · Speech organ`,
                meta: "Language Lab · Phonetics Studio",
                kind: "save",
              })
            }
          >
            {organSaved ? <Check size={14} /> : <BookmarkPlus size={14} />}
            {organSaved ? "Saved to Collection" : "Save"}
          </button>
        </aside>
      </div>

      <section className="sound-maker">
        <header>
          <div>
            <span className="eyebrow">Sound Maker</span>
            <strong>选择一个音标，观察声音如何形成</strong>
          </div>
          <Waves size={17} />
        </header>
        <div className="sound-maker__content">
          <div className="sound-maker__symbols">
            {SOUND_MAKER_ITEMS.map((item, index) => (
              <button
                type="button"
                key={item.ipa}
                className={soundIndex === index ? "is-active" : ""}
                onClick={() => setSoundIndex(index)}
              >
                {item.ipa}
              </button>
            ))}
          </div>
          <motion.div
            key={sound.ipa}
            className="sound-maker__result"
            initial={{ opacity: 0, x: 12 }}
            animate={{ opacity: 1, x: 0 }}
          >
            <strong>{sound.ipa}</strong>
            <span>
              {sound.manner} · {sound.place} ·{" "}
              {sound.voiced ? "Voiced" : "Voiceless"}
            </span>
            <p>{sound.note}</p>
            <button type="button" onClick={() => speakWord(sound.example)}>
              <Play size={13} />
              {sound.example}
            </button>
          </motion.div>
        </div>
      </section>
    </motion.div>
  );
}
